/// A reservation of a resource for a time span of one day.
public struct AffluencesReservationRequest: Codable, Hashable, Sendable {
    public var email: String
    public var date: LocalDate
    public var startTime: LocalTime
    public var endTime: LocalTime
    public var personCount: Int
    public var authType: String?
    public var note: String?
    public var userFirstName: String?
    public var userLastName: String?
    public var userPhone: String?
    public var userDeviceToken: String?

    public init(
        email: String,
        date: LocalDate,
        startTime: LocalTime,
        endTime: LocalTime,
        personCount: Int = 1,
        authType: String? = nil,
        note: String? = nil,
        userFirstName: String? = nil,
        userLastName: String? = nil,
        userPhone: String? = nil,
        userDeviceToken: String? = nil
    ) {
        self.email = email
        self.date = date
        self.startTime = startTime
        self.endTime = endTime
        self.personCount = personCount
        self.authType = authType
        self.note = note
        self.userFirstName = userFirstName
        self.userLastName = userLastName
        self.userPhone = userPhone
        self.userDeviceToken = userDeviceToken
    }

    private enum CodingKeys: String, CodingKey {
        case email = "email"
        case date = "date"
        case startTime = "start_time"
        case endTime = "end_time"
        case personCount = "person_count"
        case authType = "auth_type"
        case note = "note"
        case userFirstName = "user_firstname"
        case userLastName = "user_lastname"
        case userPhone = "user_phone"
        case userDeviceToken = "user_device_token"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.email = try container.decodeRequired(String.self, forKey: .email)
        self.date = try container.decodeRequired(LocalDate.self, forKey: .date)
        self.startTime = try container.decodeTemporalRequired(LocalTime.self, forKey: .startTime, pattern: "HH:mm", blankAsNull: false)
        self.endTime = try container.decodeTemporalRequired(LocalTime.self, forKey: .endTime, pattern: "HH:mm", blankAsNull: false)
        self.personCount = container.decodeLenient(Int.self, forKey: .personCount) ?? 1
        self.authType = container.decodeLenient(String.self, forKey: .authType)
        self.note = container.decodeLenient(String.self, forKey: .note)
        self.userFirstName = container.decodeLenient(String.self, forKey: .userFirstName)
        self.userLastName = container.decodeLenient(String.self, forKey: .userLastName)
        self.userPhone = container.decodeLenient(String.self, forKey: .userPhone)
        self.userDeviceToken = container.decodeLenient(String.self, forKey: .userDeviceToken)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(email, forKey: .email)
        try container.encode(date, forKey: .date)
        try container.encodeTemporal(startTime, forKey: .startTime, pattern: "HH:mm")
        try container.encodeTemporal(endTime, forKey: .endTime, pattern: "HH:mm")
        if personCount != 1 {
            try container.encode(personCount, forKey: .personCount)
        }
        if authType != nil {
            try container.encode(authType, forKey: .authType)
        }
        if note != nil {
            try container.encode(note, forKey: .note)
        }
        if userFirstName != nil {
            try container.encode(userFirstName, forKey: .userFirstName)
        }
        if userLastName != nil {
            try container.encode(userLastName, forKey: .userLastName)
        }
        if userPhone != nil {
            try container.encode(userPhone, forKey: .userPhone)
        }
        if userDeviceToken != nil {
            try container.encode(userDeviceToken, forKey: .userDeviceToken)
        }
    }
}

